Once AI can write decent code from scratch, it is likely it can also circumvent potential copyright violations.<p>A. Check AI generated code against a comprehensive library of open-source copyrighted code and identify potential violations.<p>B. Ask AI to generate a paraphrase of the potential violations, by employing any number of semantic preserving transforms -- e.g. variable name change, operator replacement, structured block rewrite, functional rebalance, etc.<p>Lazy example:<p><pre><code>    private static void rangeCheck(int arrayLen, int fromIndex, int toIndex {
       if (fromIndex &gt; toIndex)
          throw new IllegalArgumentException(&quot;fromIndex(&quot; + fromIndex +
               &quot;) &gt; toIndex(&quot; + toIndex+&quot;)&quot;);
       if (fromIndex &lt; 0) 
          throw new ArrayIndexOutOfBoundsException(fromIndex);
       if (toIndex &gt; arrayLen) 
          throw new ArrayIndexOutOfBoundsException(toIndex);
    }

    private static void rangeCheck(int len, int start, int end) {
       if (!(0 &lt;= start)) {
          throw new ArrayIndexOutOfBoundsException(`Failed: 0 &lt;= ${start}`);
       } else if (!(start &lt;= end)) {
          throw new IllegalArgumentException(`Failed: ${start} &lt;= ${end}`);
       } else if (!(end &lt;= len)) {
          throw new ArrayIndexOutOfBoundsException(`Failed: ${end} &lt;= ${len}`);
       }
    }</code></pre>

